
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_pbe_tca_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_pbe_tca", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.305527508399505e+00, -4.223928780049563e+00, -4.109714070516413e+00, -3.951761737991174e+00, -3.737090930246768e+00, -3.452574569141156e+00, -3.088924016078837e+00, -2.647803444506659e+00, -2.150744272062898e+00, -1.637516770046948e+00, -1.117689305499579e+00, -7.118019653472722e-01, -6.022350968179195e-01, -5.022478267187817e-01, -3.741835121111296e-01, -2.530181920377307e-01, -1.505464911631902e-01, -6.018630798572453e-02, -1.333666689130917e-02, -1.501360718953450e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


